// handler has already responded. Same script for Bun and Deno:
//  bun unread-body.ts
//  deno run --allow-net --allow-env unread-body.ts
import { connect, mib, pump, readResponse } from "./raw-client.ts"

const TOTAL = 64 * 1024 * 1024
const FIRST = 64 * 1024

const handler = async (req: Request): Promise<Response> => {
  const path = new URL(req.url).pathname
  if (path === "/health") return new Response("ok")
  if (path.startsWith("/partial")) {
  const reader = req.body!.getReader()
  await reader.read() // read one chunk, leave the rest
  if (path.endsWith("/cancel")) await reader.cancel()
  else reader.releaseLock()
  }
  const headers: Record<string, string> = new URL(req.url).searchParams.has("close") ? { connection: "close" } : {}
  return new Response("too large", { status: 413, headers })
}

const serve = async (): Promise<{ port: number; stop: () => Promise<void> | void }> => {
  if (typeof Bun !== "undefined") {
  const server = Bun.serve({ port: 0, hostname: "127.0.0.1", development: false, fetch: handler })
  return { port: server.port!, stop: () => server.stop(true) }
  }
  const server = Deno.serve({ port: 0, hostname: "127.0.0.1", onListen() {} }, handler)
  return { port: (server.addr as Deno.NetAddr).port, stop: () => server.shutdown() }
}

const runtime = typeof Bun !== "undefined" ? `Bun ${Bun.version}` : `Deno ${Deno.version.deno}`
const { port, stop } = await serve()
console.log(runtime)

const paths = ["/untouched", "/partial", "/partial/cancel", "/untouched?close", "/partial/cancel?close"]
for (const path of paths) {
  for (const framing of ["content-length", "chunked"] as const) {
  const socket = await connect(port)
  const head = framing === "content-length"
  ? `POST ${path} HTTP/1.1\r\nHost: x\r\nContent-Length: ${TOTAL}\r\n\r\n`
  : `POST ${path} HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\n\r\n${TOTAL.toString(16)}\r\n`
  socket.write(head)
  socket.write(Buffer.alloc(FIRST, 0x61))
  const response = await readResponse(socket, 3000)
  const rest = await pump(socket, TOTAL - FIRST, 1024 * 1024, 5000)
  if (framing === "chunked" && rest.end === "complete") socket.write("\r\n0\r\n\r\n")
  let reuse = "n/a"
  if (rest.end === "complete") {
  socket.write("GET /health HTTP/1.1\r\nHost: x\r\n\r\n")
  const second = await readResponse(socket, 1500)
  reuse = second.end === "open" ? second.statusLine : `${second.end}${second.errorCode ? ` (${second.errorCode})` : ""}`
  }
  console.log(`\n== ${path} (${framing})`)
  console.log(`response: ${response.statusLine} | connection: ${JSON.stringify(response.headers["connection"] ?? null)}`)
  console.log(
  `rest of body: ${mib(rest.flushed + FIRST)} of ${mib(TOTAL)} accepted in ${rest.ms} ms, then ${rest.end}${
  rest.errorCode ? ` (${rest.errorCode})` : ""
  }`
  )
  console.log(`next request on the same connection: ${reuse}`)
  socket.destroy()
  }
}

