  "dependencies": {
  "@tiptap/core": "3.27.4",
  "@tiptap/extension-code-block": "3.27.4",
  "@tiptap/pm": "3.27.4"
  },
  "overrides": {
  "prosemirror-view": "1.42.1"
  }
}
